},"data":{"key":"end","type":"end","label":"结束"}}],"edges":[{"id":"access-start-policy","source":"access-start","target":"access-policy"},{"id":"access-auto","source":"access-policy","target":"access-end","condition":{"field":"approvalPolicy","operator":"eq","value":"none"}},{"id":"access-human","source":"access-policy","target":"access-manager","condition":{"field":"approvalPolicy","operator":"in","value":"manager,manager_security,two_person"}},{"id":"access-policy-invalid","source":"access-policy","target":"access-invalid","isDefault":true},{"id":"access-manager-policy","source":"access-manager","target":"access-security-policy"},{"id":"access-manager-end","source":"access-security-policy","target":"access-end","condition":{"field":"approvalPolicy","operator":"eq","value":"manager"}},{"id":"access-with-security","source":"access-security-policy","target":"access-security","condition":{"field":"approvalPolicy","operator":"in","value":"manager_security,two_person"}},{"id":"access-security-invalid","source":"access-security-policy","target":"access-invalid","isDefault":true},{"id":"access-security-second","source":"access-security","target":"access-second-policy"},{"id":"access-single-security-end","source":"access-second-policy","target":"access-end","condition":{"field":"approvalPolicy","operator":"eq","value":"manager_security"}},{"id":"access-with-second","source":"access-second-policy","target":"access-second","condition":{"field":"approvalPolicy","operator":"eq","value":"two_person"}},{"id":"access-second-invalid","source":"access-second-policy","target":"access-invalid","isDefault":true},{"id":"access-second-end","source":"access-second","target":"access-end"},{"id":"access-invalid-end","source":"access-invalid","target":"access-end"}],"settings":{"allowWithdraw":true,"allowResubmit":false,"notifyInitiator":true,"allowComment":true,"approverDedupMode":"none","summaryFields":["targetUserName","riskLabel","expiresAt"]}}'::jsonb, '{settings}', coalesce(definition