custom_form = '{"businessType":"identity.access_request","createComponent":"biz/access/AccessRequestWorkflowForm","viewComponent":"biz/access/AccessRequestWorkflowForm","actionComponent":"biz/access/AccessRequestApprovalForm","icon":"ShieldCheck","variables":[{"key":"targetUserId","label":"目标用户","type":"user"},{"key":"reason","label":"申请原因","type":"string"},{"key":"requestType","label":"申请类型","type":"string"},{"key":"validityMode","label":"有效期限","type":"string"},{"key":"approvalPolicy","label":"有效审批策略","type":"string"},{"key":"mfaRequired","label":"审批需要 MFA","type":"boolean"},{"key":"startsAt","label":"生效时间","type":"date"},{"key":"expiresAt","label":"失效时间","type":"date"},{"key":"riskLevel","label":"风险等级","type":"string"},{"key":"permissionSummary","label":"权限摘要","type":"string"},{"key":"managerId","label":"直属主管","type":"user"},{"key":"securityApproverId","label":"安全管理员","type":"user"},{"key":"secondSecurityApproverId","label":"第二安全审批人","type":"user"}]}'::jsonb,
