INSERT INTO workflow_definition_versions (definition_id, version, name, description, flow_data, form_id, form_type, custom_form, form_schema, tenant_id)
SELECT id, version, name, description, flow_data, form_id, form_type, custom_form, NULL, tenant_id
FROM workflow_definitions WHERE custom_form->>'businessType' = 'identity.access_request' AND status = 'published'
ON CONFLICT (definition_id, version) DO NOTHING;
--> statement-breakpoint
INSERT INTO menus (id, parent_id, title, name, path, component, icon, type, sort, status, visible, feature_key)
OVERRIDING SYSTEM VALUE
VALUES (4210, 4200, '我的权限', 'MyAccess', '/access/my', 'biz/access/MyAccessPage', 'KeyRound', 'menu', 6, 'enabled', true, (SELECT feature_key FROM menus WHERE name = 'WorkflowLaunchpad' LIMIT 1))
ON CONFLICT (id) DO UPDATE SET title = excluded.title, name = excluded.name, path = excluded.path, component = excluded.component, parent_id = excluded.parent_id, visible = excluded.visible, status = excluded.status, feature_key = excluded.feature_key;
--> statement-breakpoint
INSERT INTO role_menus (role_id, menu_id)
SELECT role.id, menu.id FROM roles AS role CROSS JOIN menus AS menu
WHERE role.code = 'user' AND (
  menu.name IN ('Workflow', 'WorkflowApprovalCenter', 'WorkflowLaunchpad', 'MyApplications', 'WorkflowCcToMe', 'MyAccess')
  OR (menu.type = 'button' AND menu.permission IN ('workflow:instance:create', 'workflow:instance:list'))
)
ON CONFLICT DO NOTHING;
